create table if not exists hand_raise_queue (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete cascade, learner_id uuid, status text default 'raised', raised_at timestamptz default now(), lowered_at timestamptz, handled_by uuid, created_at timestamptz default now(), updated_at timestamptz default now()); alter table hand_raise_queue enable row level security; create index if not exists idx_hand_raise_room_status on hand_raise_queue(room_id,status);
